lessons.solution_code:
inline void swapValues(int& a, int& b) {
    int temp = a;
    a = b;
    b = temp;
}

tests.unittest_code:
int x = 10, y = 20;
swapValues(x, y);
if (x != 20 || y != 10) throw std::runtime_error("Swap failed");

